; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if1_e_go:			ld sp, if1_e
			jp ntc_xn
if7_e_go:			ld sp, if7_e
			jp ntc_xn
if12_e_go:			ld sp, if12_e
			jp ntc_xn
do13_t_go:			ld sp, do13_t
			jp ntc_xn
if15_e_go:			ld sp, if15_e
			jp ntc_xn

p_showptr_c:		; call showptr (normal)
			pop hl			; what
			ld de, var_showptr_what
			ld b, 40
p_showptr_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_showptr_si0_e
			inc hl
			inc de
			djnz p_showptr_si0
			xor a
			ld (de), a
p_showptr_si0_e:
			pop hl			; p
			ld de, var_showptr_p
			ld bc, 4
			ldir
			ld (p_showptr_rs), sp
			ld sp, p_showptr
			jp ntc_xn
p_showptr_r:		; end of showptr
			ld sp, (p_showptr_rs)
			jp ntc_xn

